-- Admin v2 (2026-10-30): pages, contact messages, newsletter, homepage sections,
-- shipping/tracking/history on orders, product stock/sale/SKU/visibility, roles,
-- checkout options. Run once in Supabase → SQL Editor BEFORE merging `admin-v2` into main.
-- Part 1 (schema) was generated by scripts/schema-sql.ts and only ADDS tables/columns.
-- Part 2 (content) creates the starting pages and homepage lists only where none exist.
-- Everything runs in one transaction: if anything fails, nothing changes.

BEGIN;

-- ===== Part 1: schema =====
CREATE TYPE "public"."enum_orders_status_history_status" AS ENUM('pending', 'confirmed', 'fulfilled', 'cancelled');
CREATE TYPE "public"."enum_contact_messages_status" AS ENUM('new', 'read', 'replied');
CREATE TYPE "public"."enum_subscribers_locale" AS ENUM('sq', 'en');
CREATE TYPE "public"."enum_products_stock_status" AS ENUM('in_stock', 'low_stock', 'out_of_stock', 'preorder');
CREATE TYPE "public"."enum_homepage_sections_section" AS ENUM('brands', 'about', 'devices', 'bestSellers', 'categories', 'why', 'newArrivals', 'education', 'promotions', 'testimonials', 'instagram', 'newsletter');
CREATE TYPE "public"."enum_homepage_why_items_icon" AS ENUM('original', 'certified', 'delivery', 'support', 'trusted');
CREATE TABLE "orders_status_history" (
	"_order" integer NOT NULL,
	"_parent_id" integer NOT NULL,
	"id" varchar PRIMARY KEY NOT NULL,
	"status" "enum_orders_status_history_status",
	"changed_at" timestamp(3) with time zone,
	"changed_by" varchar
);

CREATE TABLE "contact_messages" (
	"id" serial PRIMARY KEY NOT NULL,
	"status" "enum_contact_messages_status" DEFAULT 'new',
	"name" varchar NOT NULL,
	"clinic_name" varchar,
	"email" varchar NOT NULL,
	"phone" varchar,
	"message" varchar NOT NULL,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "subscribers" (
	"id" serial PRIMARY KEY NOT NULL,
	"email" varchar NOT NULL,
	"locale" "enum_subscribers_locale" DEFAULT 'sq',
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "pages_faq" (
	"_order" integer NOT NULL,
	"_parent_id" integer NOT NULL,
	"id" varchar PRIMARY KEY NOT NULL
);

CREATE TABLE "pages_faq_locales" (
	"question" varchar NOT NULL,
	"answer" varchar NOT NULL,
	"id" serial PRIMARY KEY NOT NULL,
	"_locale" "_locales" NOT NULL,
	"_parent_id" varchar NOT NULL
);

CREATE TABLE "pages" (
	"id" serial PRIMARY KEY NOT NULL,
	"slug" varchar NOT NULL,
	"show_in_footer" boolean DEFAULT true,
	"updated_at" timestamp(3) with time zone DEFAULT now() NOT NULL,
	"created_at" timestamp(3) with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "pages_locales" (
	"title" varchar NOT NULL,
	"intro" varchar,
	"content" jsonb,
	"meta_description" varchar,
	"id" serial PRIMARY KEY NOT NULL,
	"_locale" "_locales" NOT NULL,
	"_parent_id" integer NOT NULL
);

CREATE TABLE "homepage_sections" (
	"_order" integer NOT NULL,
	"_parent_id" integer NOT NULL,
	"id" varchar PRIMARY KEY NOT NULL,
	"section" "enum_homepage_sections_section" NOT NULL,
	"enabled" boolean DEFAULT true
);

CREATE TABLE "homepage_sections_locales" (
	"eyebrow" varchar,
	"title" varchar,
	"description" varchar,
	"id" serial PRIMARY KEY NOT NULL,
	"_locale" "_locales" NOT NULL,
	"_parent_id" varchar NOT NULL
);

CREATE TABLE "homepage_why_items" (
	"_order" integer NOT NULL,
	"_parent_id" integer NOT NULL,
	"id" varchar PRIMARY KEY NOT NULL,
	"icon" "enum_homepage_why_items_icon" DEFAULT 'original'
);

CREATE TABLE "homepage_why_items_locales" (
	"title" varchar NOT NULL,
	"description" varchar,
	"id" serial PRIMARY KEY NOT NULL,
	"_locale" "_locales" NOT NULL,
	"_parent_id" varchar NOT NULL
);

ALTER TABLE "orders" ADD COLUMN "shipping_cost" numeric;
ALTER TABLE "orders" ADD COLUMN "total" numeric;
ALTER TABLE "orders" ADD COLUMN "courier_name" varchar;
ALTER TABLE "orders" ADD COLUMN "tracking_number" varchar;
ALTER TABLE "orders" ADD COLUMN "internal_notes" varchar;
ALTER TABLE "products" ADD COLUMN "visible" boolean DEFAULT true;
ALTER TABLE "products" ADD COLUMN "compare_at_price" numeric;
ALTER TABLE "products" ADD COLUMN "sku" varchar;
ALTER TABLE "products" ADD COLUMN "stock_status" "enum_products_stock_status" DEFAULT 'in_stock';
ALTER TABLE "payload_locked_documents_rels" ADD COLUMN "contact_messages_id" integer;
ALTER TABLE "payload_locked_documents_rels" ADD COLUMN "subscribers_id" integer;
ALTER TABLE "payload_locked_documents_rels" ADD COLUMN "pages_id" integer;
