ALTER TABLE "site_settings" ADD COLUMN "checkout_options_office_payment_enabled" boolean DEFAULT true;
ALTER TABLE "site_settings" ADD COLUMN "checkout_options_bank_transfer_enabled" boolean DEFAULT true;
ALTER TABLE "site_settings" ADD COLUMN "checkout_options_cash_on_delivery_enabled" boolean DEFAULT true;
ALTER TABLE "site_settings" ADD COLUMN "checkout_options_min_order_amount" numeric;
ALTER TABLE "site_settings" ADD COLUMN "order_notification_email" varchar;
ALTER TABLE "site_settings" ADD COLUMN "legal_name" varchar;
ALTER TABLE "site_settings" ADD COLUMN "announcement_enabled" boolean DEFAULT false;
ALTER TABLE "site_settings" ADD COLUMN "announcement_link_href" varchar;
ALTER TABLE "site_settings" ADD COLUMN "logo_id" integer;
ALTER TABLE "site_settings" ADD COLUMN "english_enabled" boolean DEFAULT true;
ALTER TABLE "site_settings_locales" ADD COLUMN "opening_hours" varchar;
ALTER TABLE "site_settings_locales" ADD COLUMN "announcement_text" varchar;
ALTER TABLE "site_settings_locales" ADD COLUMN "announcement_link_label" varchar;
ALTER TABLE "site_settings_locales" ADD COLUMN "tagline" varchar;
ALTER TABLE "site_settings_locales" ADD COLUMN "top_bar_notice" varchar;
ALTER TABLE "site_settings_locales" ADD COLUMN "footer_description" varchar;
ALTER TABLE "site_settings_locales" ADD COLUMN "professional_notice" varchar;
ALTER TABLE "orders_status_history" ADD CONSTRAINT "orders_status_history_parent_id_fk" FOREIGN KEY ("_parent_id") REFERENCES "public"."orders"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "pages_faq" ADD CONSTRAINT "pages_faq_parent_id_fk" FOREIGN KEY ("_parent_id") REFERENCES "public"."pages"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "pages_faq_locales" ADD CONSTRAINT "pages_faq_locales_parent_id_fk" FOREIGN KEY ("_parent_id") REFERENCES "public"."pages_faq"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "pages_locales" ADD CONSTRAINT "pages_locales_parent_id_fk" FOREIGN KEY ("_parent_id") REFERENCES "public"."pages"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "homepage_sections" ADD CONSTRAINT "homepage_sections_parent_id_fk" FOREIGN KEY ("_parent_id") REFERENCES "public"."homepage"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "homepage_sections_locales" ADD CONSTRAINT "homepage_sections_locales_parent_id_fk" FOREIGN KEY ("_parent_id") REFERENCES "public"."homepage_sections"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "homepage_why_items" ADD CONSTRAINT "homepage_why_items_parent_id_fk" FOREIGN KEY ("_parent_id") REFERENCES "public"."homepage"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "homepage_why_items_locales" ADD CONSTRAINT "homepage_why_items_locales_parent_id_fk" FOREIGN KEY ("_parent_id") REFERENCES "public"."homepage_why_items"("id") ON DELETE cascade ON UPDATE no action;
CREATE INDEX "orders_status_history_order_idx" ON "orders_status_history" USING btree ("_order");
CREATE INDEX "orders_status_history_parent_id_idx" ON "orders_status_history" USING btree ("_parent_id");
CREATE INDEX "contact_messages_updated_at_idx" ON "contact_messages" USING btree ("updated_at");
CREATE INDEX "contact_messages_created_at_idx" ON "contact_messages" USING btree ("created_at");
