CREATE INDEX "subscribers_created_at_idx" ON "subscribers" USING btree ("created_at");
CREATE INDEX "pages_faq_order_idx" ON "pages_faq" USING btree ("_order");
CREATE INDEX "pages_faq_parent_id_idx" ON "pages_faq" USING btree ("_parent_id");
CREATE UNIQUE INDEX "pages_faq_locales_locale_parent_id_unique" ON "pages_faq_locales" USING btree ("_locale","_parent_id");
CREATE UNIQUE INDEX "pages_slug_idx" ON "pages" USING btree ("slug");
CREATE INDEX "pages_updated_at_idx" ON "pages" USING btree ("updated_at");
CREATE INDEX "pages_created_at_idx" ON "pages" USING btree ("created_at");
CREATE UNIQUE INDEX "pages_locales_locale_parent_id_unique" ON "pages_locales" USING btree ("_locale","_parent_id");
CREATE INDEX "homepage_sections_order_idx" ON "homepage_sections" USING btree ("_order");
CREATE INDEX "homepage_sections_parent_id_idx" ON "homepage_sections" USING btree ("_parent_id");
CREATE UNIQUE INDEX "homepage_sections_locales_locale_parent_id_unique" ON "homepage_sections_locales" USING btree ("_locale","_parent_id");
CREATE INDEX "homepage_why_items_order_idx" ON "homepage_why_items" USING btree ("_order");
CREATE INDEX "homepage_why_items_parent_id_idx" ON "homepage_why_items" USING btree ("_parent_id");
CREATE UNIQUE INDEX "homepage_why_items_locales_locale_parent_id_unique" ON "homepage_why_items_locales" USING btree ("_locale","_parent_id");
ALTER TABLE "payload_locked_documents_rels" ADD CONSTRAINT "payload_locked_documents_rels_contact_messages_fk" FOREIGN KEY ("contact_messages_id") REFERENCES "public"."contact_messages"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "payload_locked_documents_rels" ADD CONSTRAINT "payload_locked_documents_rels_subscribers_fk" FOREIGN KEY ("subscribers_id") REFERENCES "public"."subscribers"("id") ON DELETE cascade ON UPDATE no action;
