BEGIN
  IF NOT EXISTS (SELECT 1 FROM "pages" WHERE "slug" = 'privacy') THEN
    INSERT INTO "pages" ("slug", "show_in_footer") VALUES ('privacy', true) RETURNING "id" INTO pid;
    INSERT INTO "pages_locales" ("title", "intro", "content", "meta_description", "_locale", "_parent_id") VALUES ('Politika e Privatësisë', 'Si i mbledhim dhe i përdorim të dhënat tuaja.', '{"root":{"type":"root","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"Fillers Kosovo (Alp Estetik SHPK) respekton privatësinë tuaj. Kjo faqe shpjegon cilat të dhëna mbledhim përmes kësaj faqeje dhe si i përdorim.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"heading","tag":"h2","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"text","text":"Çfarë të dhënash mbledhim","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"Kur krijoni llogari, bëni porosi, na shkruani përmes formës së kontaktit ose regjistroheni për newsletter, mbledhim të dhënat që na jepni — emrin, emrin e klinikës, email-in, telefonin, adresën e dërgesës dhe, nëse kërkoni faturë, të dhënat e biznesit (NUI, numri fiskal, numri i TVSH-së).","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"heading","tag":"h2","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"text","text":"Si i përdorim","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"I përdorim vetëm për të menaxhuar llogarinë tuaj, për të përpunuar dhe dërguar porositë, për t''ju përgjigjur dhe — vetëm nëse jeni regjistruar — për t''ju dërguar njoftime për produkte dhe oferta. Nuk ua shesim të dhënat tuaja palëve të treta.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"heading","tag":"h2","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"text","text":"Të drejtat tuaja","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"Mund të kërkoni në çdo kohë qasje, korrigjim ose fshirje të të dhënave tuaja duke na kontaktuar përmes faqes së Kontaktit.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"Ky tekst është draft dhe duhet të rishikohet nga një jurist para lansimit zyrtar.","format":0,"style":"","mode":"normal","detail":0,"version":1}]}]}}'::jsonb, NULL, 'sq', pid);
    INSERT INTO "pages_locales" ("title", "intro", "content", "meta_description", "_locale", "_parent_id") VALUES ('Privacy Policy', 'How we collect and use your information.', '{"root":{"type":"root","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"Fillers Kosovo (Alp Estetik SHPK) respects your privacy. This page explains what information we collect through this website and how it is used.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"heading","tag":"h2","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"text","text":"Information we collect","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"When you create an account, place an order, use the contact form or subscribe to our newsletter, we collect the details you provide — your name, clinic name, email, phone, delivery address and, if you request an invoice, your business details (NUI, fiscal number, VAT number).","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"heading","tag":"h2","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"text","text":"How we use it","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"We use it only to run your account, process and deliver orders, respond to you and — only if you subscribed — send you product and promotional updates. We do not sell your personal data to third parties.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"heading","tag":"h2","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"text","text":"Your rights","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"You may request access to, correction or deletion of your personal data at any time by contacting us through the Contact page.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"This text is a draft and should be reviewed by a legal professional before the official launch.","format":0,"style":"","mode":"normal","detail":0,"version":1}]}]}}'::jsonb, NULL, 'en', pid);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM "pages" WHERE "slug" = 'terms') THEN
    INSERT INTO "pages" ("slug", "show_in_footer") VALUES ('terms', true) RETURNING "id" INTO pid;
    INSERT INTO "pages_locales" ("title", "intro", "content", "meta_description", "_locale", "_parent_id") VALUES ('Kushtet e Shitjes', 'Kushtet që vlejnë për përdorimin e faqes dhe çdo porosi.', '{"root":{"type":"root","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"Duke krijuar llogari ose duke bërë porosi në fillers-ks.com, pajtoheni me kushtet më poshtë.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"heading","tag":"h2","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"text","text":"Vetëm për përdorim profesional","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"Produktet në këtë faqe janë ekskluzivisht për mjekë të licencuar, dermatologë dhe praktikantë të certifikuar të estetikës. Rezervojmë të drejtën të verifikojmë licencën profesionale para konfirmimit të një porosie.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"heading","tag":"h2","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"text","text":"Porositë dhe çmimet","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"Çmimet, disponueshmëria dhe specifikat mund të ndryshojnë pa njoftim paraprak. Çdo porosi konfirmohet nga ekipi ynë me telefon ose email. Pajisjet e shënuara \"Kërko ofertë\" çmohen individualisht.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"heading","tag":"h2","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"text","text":"Pagesa","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"Pranojmë pagesë në zyrën tonë, me transfer bankar ose cash te korrieri për dërgesat. Për transfer bankar, porosia dërgohet pasi të konfirmohet pagesa.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"heading","tag":"h2","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"text","text":"Përgjegjësia","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"Produktet duhet të ruhen, trajtohen dhe administrohen sipas udhëzimeve zyrtare të prodhuesit. Fillers Kosovo nuk mban përgjegjësi për pasojat e ruajtjes, trajtimit ose administrimit të gabuar.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"Ky tekst është draft dhe duhet të rishikohet nga një jurist para lansimit zyrtar.","format":0,"style":"","mode":"normal","detail":0,"version":1}]}]}}'::jsonb, NULL, 'sq', pid);
    INSERT INTO "pages_locales" ("title", "intro", "content", "meta_description", "_locale", "_parent_id") VALUES ('Terms of Sale', 'The terms that apply to using this website and to every order.', '{"root":{"type":"root","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"By creating an account or placing an order on fillers-ks.com, you agree to the terms below.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"heading","tag":"h2","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"text","text":"Professional use only","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"Products on this site are intended exclusively for licensed doctors, dermatologists and certified aesthetic practitioners. We reserve the right to verify your professional license before confirming an order.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"heading","tag":"h2","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"text","text":"Orders and pricing","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"Prices, availability and specifications may change without notice. Every order is confirmed by our team by phone or email. Devices marked \"Request a quote\" are priced individually.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"heading","tag":"h2","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"text","text":"Payment","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"We accept payment at our office, by bank transfer, or cash on delivery for courier orders. For bank transfers, the order ships once payment is confirmed.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"heading","tag":"h2","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"text","text":"Liability","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"Products must be stored, handled and administered according to the manufacturer''s official instructions. Fillers Kosovo is not liable for outcomes resulting from improper storage, handling or administration.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"This text is a draft and should be reviewed by a legal professional before the official launch.","format":0,"style":"","mode":"normal","detail":0,"version":1}]}]}}'::jsonb, NULL, 'en', pid);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM "pages" WHERE "slug" = 'shipping') THEN
    INSERT INTO "pages" ("slug", "show_in_footer") VALUES ('shipping', true) RETURNING "id" INTO pid;
    INSERT INTO "pages_locales" ("title", "intro", "content", "meta_description", "_locale", "_parent_id") VALUES ('Dërgesa dhe Marrja', 'Si mund ta merrni porosinë tuaj.', '{"root":{"type":"root","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"heading","tag":"h2","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"text","text":"Marrje në zyrën tonë","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"Mund ta merrni porosinë në zyrën tonë sapo t''ju njoftojmë që është gati — pa kosto dërgese.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"heading","tag":"h2","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"text","text":"Dërgesë me korrier","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"Dërgojmë kudo në Kosovë dhe Shqipëri me logjistikë të përshtatshme për produkte farmaceutike dhe biologjike. Porositë standarde zakonisht arrijnë brenda 24–48 orëve pas konfirmimit. Nëse keni nevojë për një datë të caktuar, zgjidheni në checkout.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"heading","tag":"h2","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"text","text":"Ruajtja gjatë transportit","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"Produktet e ndjeshme ndaj temperaturës dërgohen me paketim të përshtatshëm (zinxhir i ftohtë). Kontrolloni pakon kur e pranoni dhe na kontaktoni menjëherë nëse paketimi duket i dëmtuar.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"Ky tekst është draft dhe duhet të rishikohet nga një jurist para lansimit zyrtar.","format":0,"style":"","mode":"normal","detail":0,"version":1}]}]}}'::jsonb, NULL, 'sq', pid);
    INSERT INTO "pages_locales" ("title", "intro", "content", "meta_description", "_locale", "_parent_id") VALUES ('Delivery and Pickup', 'How you can receive your order.', '{"root":{"type":"root","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"heading","tag":"h2","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"text","text":"Pickup at our office","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"You can collect your order at our office as soon as we let you know it''s ready — no delivery cost.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"heading","tag":"h2","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"text","text":"Courier delivery","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"We deliver anywhere in Kosovo and Albania with logistics suited to pharmaceutical and biological products. Standard orders usually arrive within 24–48 hours of confirmation. If you need a specific date, choose it at checkout.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"heading","tag":"h2","format":"","indent":0,"version":1,"direction":"ltr","children":[{"type":"text","text":"Storage in transit","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"Temperature-sensitive products ship with appropriate cold-chain packaging. Please inspect the parcel on arrival and contact us immediately if the packaging looks damaged.","format":0,"style":"","mode":"normal","detail":0,"version":1}]},{"type":"paragraph","format":"","indent":0,"version":1,"direction":"ltr","textFormat":0,"children":[{"type":"text","text":"This text is a draft and should be reviewed by a legal professional before the official launch.","format":0,"style":"","mode":"normal","detail":0,"version":1}]}]}}'::jsonb, NULL, 'en', pid);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM "pages" WHERE "slug" = 'faq') THEN
    INSERT INTO "pages" ("slug", "show_in_footer") VALUES ('faq', true) RETURNING "id" INTO pid;
    INSERT INTO "pages_locales" ("title", "intro", "content", "meta_description", "_locale", "_parent_id") VALUES ('Pyetjet e Shpeshta', 'Përgjigje të shpejta për pyetjet që na bëhen më shpesh.', NULL, NULL, 'sq', pid);
    INSERT INTO "pages_locales" ("title", "intro", "content", "meta_description", "_locale", "_parent_id") VALUES ('Frequently Asked Questions', 'Quick answers to the questions we hear most often.', NULL, NULL, 'en', pid);
    INSERT INTO "pages_faq" ("_order", "_parent_id", "id") VALUES (1, pid, '6ae46eb3ea51d1394035fc1e');
    INSERT INTO "pages_faq_locales" ("question", "answer", "_locale", "_parent_id") VALUES ('Kush mund të blejë në këtë faqe?', 'Vetëm mjekë të licencuar, dermatologë dhe klinika të certifikuara të estetikës. Mund të kërkojmë verifikim të licencës para konfirmimit të porosisë.', 'sq', '6ae46eb3ea51d1394035fc1e');
    INSERT INTO "pages_faq_locales" ("question", "answer", "_locale", "_parent_id") VALUES ('Who can buy on this website?', 'Only licensed doctors, dermatologists and certified aesthetic clinics. We may ask to verify your license before confirming an order.', 'en', '6ae46eb3ea51d1394035fc1e');
    INSERT INTO "pages_faq" ("_order", "_parent_id", "id") VALUES (2, pid, '6ae46eb3ea51d1394035fc1f');
    INSERT INTO "pages_faq_locales" ("question", "answer", "_locale", "_parent_id") VALUES ('A janë produktet origjinale?', 'Po. Jemi distributor i autorizuar dhe çdo produkt vjen me numër batch-i të gjurmueshëm nga prodhuesi.', 'sq', '6ae46eb3ea51d1394035fc1f');
    INSERT INTO "pages_faq_locales" ("question", "answer", "_locale", "_parent_id") VALUES ('Are the products original?', 'Yes. We are an authorised distributor and every product comes with a traceable manufacturer batch number.', 'en', '6ae46eb3ea51d1394035fc1f');
    INSERT INTO "pages_faq" ("_order", "_parent_id", "id") VALUES (3, pid, '6ae46eb3ea51d1394035fc20');
    INSERT INTO "pages_faq_locales" ("question", "answer", "_locale", "_parent_id") VALUES ('Si mund ta marr porosinë?', 'Mund ta merrni në zyrën tonë ose ta dërgojmë me korrier në adresën tuaj. Te checkout mund të zgjidhni edhe një datë të caktuar.', 'sq', '6ae46eb3ea51d1394035fc20');
    INSERT INTO "pages_faq_locales" ("question", "answer", "_locale", "_parent_id") VALUES ('How can I receive my order?', 'Pick it up at our office or have it delivered by courier to your address. At checkout you can also choose a specific date.', 'en', '6ae46eb3ea51d1394035fc20');
    INSERT INTO "pages_faq" ("_order", "_parent_id", "id") VALUES (4, pid, '6ae46eb3ea51d1394035fc21');
    INSERT INTO "pages_faq_locales" ("question", "answer", "_locale", "_parent_id") VALUES ('Si mund të paguaj?', 'Në zyrën tonë (cash ose kartelë), me transfer bankar, ose cash te korrieri kur porosia dërgohet me korrier.', 'sq', '6ae46eb3ea51d1394035fc21');
    INSERT INTO "pages_faq_locales" ("question", "answer", "_locale", "_parent_id") VALUES ('How can I pay?', 'At our office (cash or card), by bank transfer, or cash on delivery for courier orders.', 'en', '6ae46eb3ea51d1394035fc21');
    INSERT INTO "pages_faq" ("_order", "_parent_id", "id") VALUES (5, pid, '6ae46eb3ea51d1394035fc22');
    INSERT INTO "pages_faq_locales" ("question", "answer", "_locale", "_parent_id") VALUES ('A mund të marr faturë për biznesin tim?', 'Po. Te checkout tikoni "Më duhet faturë për biznes" dhe shkruani emrin e biznesit dhe NUI-n.', 'sq', '6ae46eb3ea51d1394035fc22');
    INSERT INTO "pages_faq_locales" ("question", "answer", "_locale", "_parent_id") VALUES ('Can I get an invoice for my business?', 'Yes. At checkout tick "I need a business invoice" and enter your business name and NUI.', 'en', '6ae46eb3ea51d1394035fc22');
    INSERT INTO "pages_faq" ("_order", "_parent_id", "id") VALUES (6, pid, '6ae46eb3ea51d1394035fc23');
    INSERT INTO "pages_faq_locales" ("question", "answer", "_locale", "_parent_id") VALUES ('Kam harruar fjalëkalimin e llogarisë. Çfarë të bëj?', 'Na kontaktoni me telefon ose email dhe ua rivendosim.', 'sq', '6ae46eb3ea51d1394035fc23');
    INSERT INTO "pages_faq_locales" ("question", "answer", "_locale", "_parent_id") VALUES ('I forgot my account password. What should I do?', 'Contact us by phone or email and we''ll reset it for you.', 'en', '6ae46eb3ea51d1394035fc23');
  END IF;
