  IF hid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "homepage_why_items") THEN
    INSERT INTO "homepage_why_items" ("_order", "_parent_id", "id", "icon") VALUES (1, hid, 'ab5cb40442e36a17a89a0197', 'original');
    INSERT INTO "homepage_why_items_locales" ("title", "description", "_locale", "_parent_id") VALUES ('Produkte Origjinale', 'Çdo njësi e siguruar direkt nga prodhuesit, me gjurmueshmëri të plotë të batch-it dhe dokumentacion.', 'sq', 'ab5cb40442e36a17a89a0197'), ('Original Products', 'Every unit sourced directly from manufacturers, with full batch traceability and documentation.', 'en', 'ab5cb40442e36a17a89a0197');
    INSERT INTO "homepage_why_items" ("_order", "_parent_id", "id", "icon") VALUES (2, hid, '2873c75d80cd154402c16229', 'certified');
    INSERT INTO "homepage_why_items_locales" ("title", "description", "_locale", "_parent_id") VALUES ('Distributor i Certifikuar', 'Zyrtarisht i autorizuar për shpërndarje në gjithë Kosovën, në përputhje me standardet rajonale rregullatore.', 'sq', '2873c75d80cd154402c16229'), ('Certified Distributor', 'Officially authorized to distribute across Kosovo, meeting regional regulatory standards.', 'en', '2873c75d80cd154402c16229');
    INSERT INTO "homepage_why_items" ("_order", "_parent_id", "id", "icon") VALUES (3, hid, 'ef0c53a627da8729f2b486f2', 'delivery');
    INSERT INTO "homepage_why_items_locales" ("title", "description", "_locale", "_parent_id") VALUES ('Dërgesë e Shpejtë', 'Logjistikë me temperaturë të kontrolluar, me dërgesë në gjithë Kosovën brenda 24–48 orësh.', 'sq', 'ef0c53a627da8729f2b486f2'), ('Fast Delivery', 'Temperature-controlled logistics with delivery across Kosovo in as little as 24–48 hours.', 'en', 'ef0c53a627da8729f2b486f2');
    INSERT INTO "homepage_why_items" ("_order", "_parent_id", "id", "icon") VALUES (4, hid, '70f8fdaa1d99f46259b9e0b1', 'support');
    INSERT INTO "homepage_why_items_locales" ("title", "description", "_locale", "_parent_id") VALUES ('Mbështetje Profesionale', 'Një ekip i dedikuar specialistësh që ofron udhëzime protokolli dhe njohuri klinike për produktet.', 'sq', '70f8fdaa1d99f46259b9e0b1'), ('Professional Support', 'A dedicated team of specialists offering protocol guidance and clinical product knowledge.', 'en', '70f8fdaa1d99f46259b9e0b1');
    INSERT INTO "homepage_why_items" ("_order", "_parent_id", "id", "icon") VALUES (5, hid, 'e80d0e67eb8f92c68fafba8d', 'trusted');
    INSERT INTO "homepage_why_items_locales" ("title", "description", "_locale", "_parent_id") VALUES ('Brende të Besuara', '14 brende udhëheqëse globale, të përzgjedhura për efikasitet, siguri dhe rezultate klinike të qëndrueshme.', 'sq', 'e80d0e67eb8f92c68fafba8d'), ('Trusted Brands', '14 leading global brands, curated for efficacy, safety and consistent clinical outcomes.', 'en', 'e80d0e67eb8f92c68fafba8d');
  END IF;
END $$;

